const results = $input.first().json.results || [];
if (results.length === 0) { return [{ json: { mode: 'ideate' } }]; }
const r = results[0];
return [{ json: {
  mode: 'draft',
  pageId: r.id,
  title: r.properties?.Title?.title?.[0]?.plain_text || 'Untitled',
  hook: r.properties?.Hook?.rich_text?.[0]?.plain_text || ''
} }];

// Notion rich_text items cap at 2000 chars — chunk the draft.
const text = ($input.first().json.content?.[0]?.text) || '';
if (!text) { throw new Error('Claude returned no draft'); }
const chunks = [];
for (let i = 0; i < text.length && chunks.length < 90; i += 1900) { chunks.push({ text: { content: text.slice(i, i + 1900) } }); }
return [{ json: { pageId: $('Idea or Ideate?').first().json.pageId, title: $('Idea or Ideate?').first().json.title, chunks } }];

