const text = ($input.first().json.content?.[0]?.text) || '[]';
const match = text.match(/\[[\s\S]*\]/);
let ideas = [];
try { ideas = JSON.parse(match ? match[0] : text); } catch (e) { throw new Error('Could not parse ideas JSON: ' + text.slice(0, 200)); }
return ideas.slice(0, 3).map(i => ({ json: { title: String(i.title || '').slice(0, 200), hook: String(i.hook || '').slice(0, 500) } }));
